package com.luci.pianoroom;
import java.io.*;import java.nio.*;import java.nio.file.*;import java.util.zip.*;
public final class SfzBankTest {
 static void check(boolean b,String s){if(!b)throw new AssertionError(s);}
 static void wave(File file,int channels,int seed)throws IOException{int frames=2048;ByteBuffer b=ByteBuffer.allocate(44+frames*channels*3).order(ByteOrder.LITTLE_ENDIAN);b.put(new byte[]{82,73,70,70}).putInt(b.capacity()-8).put(new byte[]{87,65,86,69,102,109,116,32}).putInt(16).putShort((short)1).putShort((short)channels).putInt(48000).putInt(48000*channels*3).putShort((short)(channels*3)).putShort((short)24).put(new byte[]{100,97,116,97}).putInt(frames*channels*3);for(int i=0;i<frames;i++)for(int ch=0;ch<channels;ch++){int v=(int)(Math.sin(i*.03)*(seed+ch*9000))+1;b.put((byte)v).put((byte)(v>>8)).put((byte)(v>>16));}Files.write(file.toPath(),b.array());}
 static void codec(File root,int format,int bits)throws Exception{int width=bits/8;File wav=new File(root,"codec-"+format+"-"+bits+".wav");ByteBuffer b=ByteBuffer.allocate(44+16*width).order(ByteOrder.LITTLE_ENDIAN);b.put(new byte[]{82,73,70,70}).putInt(b.capacity()-8).put(new byte[]{87,65,86,69,102,109,116,32}).putInt(16).putShort((short)format).putShort((short)1).putInt(44100).putInt(44100*width).putShort((short)width).putShort((short)bits).put(new byte[]{100,97,116,97}).putInt(16*width);for(int i=0;i<16;i++){float value=(i&1)==0?.25f:-.25f;if(format==3)b.putFloat(value);else if(bits==16)b.putShort((short)(value*32768));else b.putInt((int)(value*2147483648.0));}Files.write(wav.toPath(),b.array());File sfz=new File(root,"codec.sfz"),packed=new File(root,"codec.prb");Files.write(sfz.toPath(),("<region> sample="+wav.getName()+" key=60").getBytes("UTF-8"));SfzBank.compile(sfz,root,packed,"Codec");ByteBuffer data=ByteBuffer.wrap(Files.readAllBytes(packed.toPath())).order(ByteOrder.LITTLE_ENDIAN);check(data.getFloat(172)==.25f&&data.getFloat(176)==-.25f,"PCM/float codec preserves signed amplitude");}
 public static void main(String[]args)throws Exception{File root=new File(args[0]);root.mkdirs();codec(root,1,16);codec(root,1,32);codec(root,3,32);wave(new File(root,"one.wav"),2,2000000);wave(new File(root,"two.wav"),2,4000000);wave(new File(root,"release.wav"),1,1000000);File sfz=new File(root,"instrument.sfz");String source="<global> key=C4 ampeg_release=0.2\n<group> seq_length=2 loop_mode=loop_sustain loop_start=10 loop_end=2000\n<region> sample=one.wav seq_position=1\n<region> sample=two.wav seq_position=2\n<group>\n<region> sample=release.wav trigger=release_key\n<region> sample=release.wav trigger=release\n";Files.write(sfz.toPath(),source.getBytes("UTF-8"));File target=new File(root,"fixture.prb");String report=SfzBank.compile(sfz,root,target,"Test bank");check(target.length()>1024&&report.contains("float32"),"compiled 24-bit stereo");Files.write(sfz.toPath(),"<region> sample=one.wav cutoff=3000".getBytes("UTF-8"));try{SfzBank.compile(sfz,root,new File(root,"bad.prb"),"Bad");throw new AssertionError("unsupported accepted");}catch(IOException e){check(e.getMessage().contains("cutoff"),"unsupported reported");}Files.write(sfz.toPath(),"<region> sample=../escape.wav".getBytes("UTF-8"));try{SfzBank.compile(sfz,root,new File(root,"bad.prb"),"Bad");throw new AssertionError("escape accepted");}catch(IOException expected){}ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(ZipOutputStream zip=new ZipOutputStream(bytes)){zip.putNextEntry(new ZipEntry("../escape.sfz"));zip.write(1);zip.closeEntry();}SfzBank.erase(new File(root,"unsafe"));try{SfzBank.unpack(new ByteArrayInputStream(bytes.toByteArray()),new File(root,"unsafe"));throw new AssertionError("ZipSlip accepted");}catch(IOException expected){}check(!new File(root.getParentFile(),"escape.sfz").exists(),"ZIP stays in import directory");System.out.println("SFZ importer: PCM16/24/32/float32, signed amplitudes, stereo/regions, unsupported opcode reporting and path containment passed");}
}
